item.text:
{
  "authorities": [
    {
      "authority_id": "circular.material_changes",
      "source_kind": "CIRCULAR",
      "proposition": "The circular removes the SFC's prior-approval requirement for material changes in investment objectives, policies and restrictions of covered UCITS funds where the changes comply with home-jurisdiction requirements, subject to the product-feature and local-policy exceptions and the application transition. Materiality alone therefore does not establish that prior approval remains required.",
      "text_role": "OPERATIVE_PROVISION",
      "role_basis": [
        {
          "unit_id": "d97b56331f41a.u5.840",
          "quote": "Removing the SFC’s requirement on prior approval for material changes in investment objectives, policies and restrictions which comply with the fund’s home jurisdiction requirements, except for changes that involve novel or complex product features and/or which may have local policy implications."
        }
      ],
      "jurisdiction": "Hong Kong",
      "actor_class": "Selected regulated actor",
      "relevant_factors": [
        "Whether the fund falls within the circular's express definition of UCITS funds.",
        "Whether the change concerns a post-authorisation investment objective, policy or restriction.",
        "Whether the change complies with the fund's home-jurisdiction requirements.",
        "Whether the change involves novel or complex product features or may have local policy implications.",
        "Whether a pending application falls within the transition for applications received before 28 November 2025."
      ],
      "applicability": "PROPOSED_APPLICABLE",
      "applicability_basis": [
        {
          "unit_id": "d97b56331f41a.u17.2556",
          "quote": "For this circular, UCITS funds means (i) Undertakings for Collective Investment in Transferable Securities (UCITS) domiciled in France, Luxembourg, Ireland and the Netherlands, and (ii) collective investment schemes domiciled in the United Kingdom authorised as UK UCITS."
        },
        {
          "unit_id": "d97b56331f41a.u3.575",
          "quote": "The key streamlined measures cover the following post-authorisation matters:"
        },
        {
          "unit_id": "d97b56331f41a.u5.840",
          "quote": "Removing the SFC’s requirement on prior approval for material changes in investment objectives, policies and restrictions which comply with the fund’s home jurisdiction requirements, except for changes that involve novel or complex product features and/or which may have local policy implications."
        }
      ],
      "effective_from": "2025-11-28",
      "effective_until": null,
      "temporal_basis": [
        {
          "unit_id": "d97b56331f41a.u9.1696",
          "quote": "The streamlined measures set out in the relevant FAQs will take effect on 28 November 2025 (Effective Date)."
        },
        {
          "unit_id": "d97b56331f41a.u1.190",
          "quote": "These measures aim at facilitating UCITS funds in implementing changes that are subject to their home regulator’s supervision, and will take immediate effect."
        }
      ],
      "treatment": "NO_TREATMENT_ESTABLISHED",
      "treatment_basis": [],
      "assumptions": [
        "Proposed applicability identifies the provision relevant to the selected question; the packet does not establish that any particular fund or change satisfies its conditions.",
        "The dated implementation clause is read as specifying the date meant by the general statement that the measures take immediate effect; publication is not used to infer effectiveness.",
        "The referenced FAQs and their detailed conditions have not been supplied.",
        "No end date or subsequent amendment is established by the supplied text; a null effective_until does not establish continued effectiveness through the assessment date."
      ]
    },
    {
      "authority_id": "circular.exceptions",
      "source_kind": "CIRCULAR",
      "proposition": "A change involving novel or complex product features, or which may have local policy implications, is excepted from the stated removal of prior approval. The circular does not supply the detailed approval rules governing those excepted changes. Failure to satisfy home-jurisdiction requirements likewise prevents reliance on the stated removal, without itself establishing that SFC approval could cure that failure.",
      "text_role": "OPERATIVE_PROVISION",
      "role_basis": [
        {
          "unit_id": "d97b56331f41a.u5.840",
          "quote": "Removing the SFC’s requirement on prior approval for material changes in investment objectives, policies and restrictions which comply with the fund’s home jurisdiction requirements, except for changes that involve novel or complex product features and/or which may have local policy implications."
        }
      ],
      "jurisdiction": "Hong Kong",
      "actor_class": "Selected regulated actor",
      "relevant_factors": [
        "Novel product features.",
        "Complex product features.",
        "Potential local policy implications.",
        "Compliance with home-jurisdiction requirements.",
        "The applicable underlying approval rules and FAQ guidance."
      ],
      "applicability": "UNRESOLVED",
      "applicability_basis": [
        {
          "unit_id": "d97b56331f41a.u5.840",
          "quote": "except for changes that involve novel or complex product features and/or which may have local policy implications."
        }
      ],
      "effective_from": "2025-11-28",
      "effective_until": null,
      "temporal_basis": [
        {
          "unit_id": "d97b56331f41a.u9.1696",
          "quote": "The streamlined measures set out in the relevant FAQs will take effect on 28 November 2025 (Effective Date)."
        }
      ],
      "treatment": "NO_TREATMENT_ESTABLISHED",
      "treatment_basis": [],
      "assumptions": [
        "The packet contains no facts permitting classification of the proposed change as novel, complex or potentially carrying local policy implications.",
        "An exception from removal of an approval requirement is not treated as a complete, independently specified approval regime.",
        "The dated implementation clause is read as applying to the exception as part of the streamlined measure."
      ]
    },
    {
      "authority_id": "circular.pending_applications",
      "source_kind": "CIRCULAR",
      "proposition": "Applications received by the SFC before 28 November 2025 for which approval or authorisation had not been granted remain subject to the existing approval or authorisation process. The new removal should therefore not be assumed to release an application within that transitional category from its existing process.",
      "text_role": "OPERATIVE_PROVISION",
      "role_basis": [
        {
          "unit_id": "d97b56331f41a.u10.1809",
          "quote": "Existing applications received by the SFC before the Effective Date for which no approval or authorisation has been granted will be processed by the SFC in accordance with the existing approval or authorisation process."
        }
      ],
      "jurisdiction": "Hong Kong",
      "actor_class": "Selected regulated actor",
      "relevant_factors": [
        "The date the SFC received the application.",
        "Whether approval or authorisation had been granted when the transition took effect.",
        "Whether the application concerns the material investment change under assessment.",
        "The content of the existing approval or authorisation process."
      ],
      "applicability": "UNRESOLVED",
      "applicability_basis": [
        {
          "unit_id": "d97b56331f41a.u10.1809",
          "quote": "Existing applications received by the SFC before the Effective Date for which no approval or authorisation has been granted will be processed by the SFC in accordance with the existing approval or authorisation process."
        }
      ],
      "effective_from": "2025-11-28",
      "effective_until": null,
      "temporal_basis": [
        {
          "unit_id": "d97b56331f41a.u9.1696",
          "quote": "The streamlined measures set out in the relevant FAQs will take effect on 28 November 2025 (Effective Date)."
        },
        {
          "unit_id": "d97b56331f41a.u10.1809",
          "quote": "Existing applications received by the SFC before the Effective Date for which no approval or authorisation has been granted will be processed by the SFC in accordance with the existing approval or authorisation process."
        }
      ],
      "treatment": "NO_TREATMENT_ESTABLISHED",
      "treatment_basis": [],
      "assumptions": [
        "The reference to existing unapproved applications is read as referring to their status at the Effective Date.",
        "The packet does not establish an application's receipt date or approval status.",
        "The transitional provision preserves an existing process without supplying its complete requirements or a calendar end date."
      ]
    },
    {
      "authority_id": "circular.post_vetting",
      "source_kind": "CIRCULAR",
      "proposition": "The SFC states that it will continue post-vetting scheme changes and related revised documents filed with it, including changes exempt from prior approval, and may make enquiries or take regulatory action for non-compliance. Removal of prior approval therefore does not establish freedom from subsequent regulatory scrutiny.",
      "text_role": "OPERATIVE_PROVISION",
      "role_basis": [
        {
          "unit_id": "d97b56331f41a.u12.2069",
          "quote": "The SFC will continue to conduct post-vetting of scheme changes (including those not subject to the SFC’s prior approval) and related revised documents filed with the SFC. It may make follow-up enquiries and/or take appropriate regulatory actions in case of non-compliance to ensure investor protection."
        }
      ],
      "jurisdiction": "Hong Kong",
      "actor_class": "Securities and Futures Commission",
      "relevant_factors": [
        "A scheme change and related revised documents filed with the SFC.",
        "Potential non-compliance.",
        "Post-vetting applies even where prior approval is not required."
      ],
      "applicability": "PROPOSED_APPLICABLE",
      "applicability_basis": [
        {
          "unit_id": "d97b56331f41a.u12.2069",
          "quote": "The SFC will continue to conduct post-vetting of scheme changes (including those not subject to the SFC’s prior approval) and related revised documents filed with the SFC."
        }
      ],
      "effective_from": null,
      "effective_until": null,
      "temporal_basis": [
        {
          "unit_id": "d97b56331f41a.u12.2069",
          "quote": "The SFC will continue to conduct post-vetting of scheme changes (including those not subject to the SFC’s prior approval) and related revised documents filed with the SFC."
        }
      ],
      "treatment": "NO_TREATMENT_ESTABLISHED",
      "treatment_basis": [],
      "assumptions": [
        "OPERATIVE_PROVISION identifies a substantive statement of regulatory practice in the circular, not legislation or an independently established statutory power.",
        "The word continue does not establish the original commencement date of post-vetting.",
        "Possible regulatory action for non-compliance is not evidence of adverse treatment of this circular or of any decided case."
      ]
    }
  ],
  "priorities": [
    {
      "priority_id": "priority.express_exception",
      "preferred": "circular.exceptions",
      "displaced": "circular.material_changes",
      "rationale": "The source expressly excepts the specified product-feature and local-policy changes from removal of prior approval. This is a conditional limitation within the same circular, not a finding that one authority overrules another. Whether the exception is triggered remains unresolved.",
      "evidence": [
        {
          "unit_id": "d97b56331f41a.u5.840",
          "quote": "except for changes that involve novel or complex product features and/or which may have local policy implications."
        }
      ],
      "premise_status": "SOURCE_EXPRESS"
    },
    {
      "priority_id": "priority.application_transition",
      "preferred": "circular.pending_applications",
      "displaced": "circular.material_changes",
      "rationale": "For applications satisfying the stated receipt-date and pending-status conditions, the circular expressly preserves the existing process. That specific transition qualifies reliance on the general removal of prior approval; it does not displace the removal for all later changes.",
      "evidence": [
        {
          "unit_id": "d97b56331f41a.u10.1809",
          "quote": "Existing applications received by the SFC before the Effective Date for which no approval or authorisation has been granted will be processed by the SFC in accordance with the existing approval or authorisation process."
        },
        {
          "unit_id": "d97b56331f41a.u9.1696",
          "quote": "The streamlined measures set out in the relevant FAQs will take effect on 28 November 2025 (Effective Date)."
        }
      ],
      "premise_status": "SOURCE_EXPRESS"
    }
  ],
  "unresolved": [
    "The particular fund's domicile, UK UCITS authorisation where relevant, and post-authorisation status are not supplied.",
    "The proposed change and evidence of compliance with home-jurisdiction requirements are not supplied.",
    "Whether the change involves novel or complex product features or may have local policy implications requires facts and applicable interpretive guidance absent from the packet.",
    "The referenced FAQs, forms and checklists are not supplied. The circular's reference to them does not establish their contents, independent applicability or legal status, and does not convert the circular into an FAQ or official answer.",
    "The two listed missing dependencies have no supplied text or source hashes; their substantive effect cannot be assessed.",
    "The existing approval or authorisation process, including the precise requirements applicable to excepted changes and transitional applications, is not supplied.",
    "No application receipt date or approval status is supplied, so the transition cannot be applied conclusively.",
    "The explicit Effective Date precedes the assessment date of 28 September 2026, but the retained packet alone does not establish whether subsequent instruments amended, superseded or otherwise affected the circular.",
    "The supplied passages contain no holding, submission or established adverse treatment. Their normative labels do not independently establish binding legal force."
  ]
}
